/bin/bash -lc "node --input-type=module <<'EOF'
import { createServer } from './src/server.js';
const server = createServer({ baseUrl: 'https://app.test', projectAdmins: { demo: ['admin'] } });
await new Promise(resolve => server.listen(0, resolve));
const url = "'`http://127.0.0.1:${server.address().port}`;
const headers = { authorization:'"'Bearer admin', 'content-type':'application/json', 'idempotency-key':'workflow-1' };
const a = await fetch("'`${url}/api/projects/demo/invites`, { method:'"'POST', headers, body:JSON.stringify({email:'member@example.com', role:'editor'}) });
const first = await a.json();
const b = await fetch("'`${url}/api/projects/demo/invites`, { method:'"'POST', headers, body:JSON.stringify({email:'changed@example.com', role:'viewer'}) });
const second = await b.json();
console.log(JSON.stringify({status:a.status, replayStatus:b.status, sameInvite:first.inviteUrl===second.inviteUrl, role:first.role, pageStatus:(await fetch(url)).status}));
server.close();
EOF"

